using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
public static class CaptureIsland023 {
 public static object Main(){string dir="/Users/bruno.duartec/Documents/Projects/Freyja/Artifacts/Island023";Directory.CreateDirectory(dir);var go=new GameObject("Capture023_temp");var c=go.AddComponent<Camera>();c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.13f,.46f,.53f);c.nearClipPlane=.3f;c.farClipPlane=800;c.fieldOfView=42;c.allowHDR=false;c.allowMSAA=false;
 Shot(c,dir+"/geral.png",new Vector3(12,113,-153),new Vector3(0,8,0));Shot(c,dir+"/cais-praia.png",new Vector3(-67,40,-92),new Vector3(-15,2,-39));Shot(c,dir+"/centro-igreja.png",new Vector3(25,51,-48),new Vector3(0,10,17));Shot(c,dir+"/casa-isolada.png",new Vector3(-71,38,15),new Vector3(-49,17,39));UnityEngine.Object.DestroyImmediate(go);return dir;}
 static void Shot(Camera c,string path,Vector3 pos,Vector3 target){c.transform.position=pos;c.transform.LookAt(target);var rt=new RenderTexture(1280,960,24);c.targetTexture=rt;c.Render();var old=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(1280,960,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1280,960),0,0);tex.Apply();File.WriteAllBytes(path,tex.EncodeToPNG());RenderTexture.active=old;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);}
}
